class SSHWorker(QThread):
    progress_updated = pyqtSignal(int)
    output_received = pyqtSignal(str)
    finished = pyqtSignal(bool, str)
    url_generated = pyqtSignal(str)

    def __init__(self, hostname, username, password, root_password):
        super().__init__()
        self.hostname = hostname
        self.username = username
        self.password = password
        self.root_password = root_password
        self.is_running = True
        self.detected_ip = ""

    def run(self):
        try:
            self.output_received.emit(f"⌛ Connecting to FRESH server {self.hostname}...")
            ssh = paramiko.SSHClient()
            ssh.set_missing_host_key_policy(paramiko.AutoAddPolicy())
            ssh.connect(
                self.hostname,
                username=self.username,
                password=self.password,
                timeout=30
            )
            self.progress_updated.emit(5)

            self.output_received.emit("⚙️ Generating Official Installation Script (Fixed)...")
            script = self.generate_install_script()
            remote_filename = "netbox_perfect_install.sh"

            sftp = ssh.open_sftp()
            remote_path = f"/tmp/{remote_filename}"
            with sftp.file(remote_path, 'w') as remote_file:
                remote_file.write(script)
            sftp.chmod(remote_path, 0o755)
            sftp.close()
            self.progress_updated.emit(10)

            self.output_received.emit("🚀 Starting Installation on Clean Ubuntu...")
            command = f"echo '{self.root_password}' | sudo -S bash {remote_path}"
            self.progress_updated.emit(15)

            channel = ssh.get_transport().open_session()
            channel.get_pty() 
            channel.exec_command(command)
            self.monitor_ssh_channel(channel, ssh, remote_path)

        except Exception as e:
            self.output_received.emit(f"❌ Error: {str(e)}")
            self.finished.emit(False, str(e))

    def generate_install_script(self):
        db_password = self.password
        secret_key = secrets.token_hex(50)
        csrf_trusted = f"https://{self.hostname}"
        
        return f"""#!/bin/bash
# --- NetBox Perfect Install Script (Official Method Fixed) ---
# Designed for clean Ubuntu 24.04 installs
set -e
set -o pipefail

verify_step() {{
    if [ $? -eq 0 ]; then
        echo "✅ CHECK PASS: $1"
    else
        echo "❌ CHECK FAILED: $1"
        exit 1
    fi
}}

check_service() {{
    echo ">> Verifying service: $1..."
    if systemctl is-active --quiet $1; then
        echo "✅ Service $1 is RUNNING."
    else
        echo "❌ Service $1 is NOT running."
        exit 1
    fi
}}

echo ">> 1. Updating system packages..."
export DEBIAN_FRONTEND=noninteractive
# Disable restart dialogs
echo '$nrconf{{restart}} = "a";' | sudo tee /etc/needrestart/conf.d/50local.conf > /dev/null || true
sudo apt update -q
sudo apt upgrade -y -q
verify_step "System Update"

echo ">> 2. Installing System Dependencies..."
# Comprehensive list for Ubuntu 24.04 including pkg-config
sudo apt install -y python3 python3-pip python3-venv python3-dev build-essential libxml2-dev libxslt1-dev libffi-dev libpq-dev libssl-dev zlib1g-dev git postgresql postgresql-contrib redis-server nginx openssl pkg-config curl jq
verify_step "Dependencies Installation"

echo ">> 3. Preparing Database Services..."
sudo systemctl enable --now postgresql
sudo systemctl enable --now redis-server

# Wait for DB to be truly ready
TIMEOUT=30
while ! sudo -u postgres pg_isready -q; do
  TIMEOUT=$((TIMEOUT-1))
  if [ $TIMEOUT -eq 0 ]; then echo "❌ PostgreSQL timed out"; exit 1; fi
  sleep 1
done
echo "✅ PostgreSQL is accepting connections."
check_service redis-server

echo ">> 4. Configuring PostgreSQL..."
# Idempotent database creation (safe to run multiple times)
sudo -u postgres psql -c "CREATE DATABASE netbox;" || true
sudo -u postgres psql -c "CREATE USER netbox WITH PASSWORD '{db_password}';" || sudo -u postgres psql -c "ALTER USER netbox WITH PASSWORD '{db_password}';"
sudo -u postgres psql -c "ALTER DATABASE netbox OWNER TO netbox;"
sudo -u postgres psql -c "GRANT ALL PRIVILEGES ON DATABASE netbox TO netbox;"
verify_step "PostgreSQL Configuration"

echo ">> 5. Cloning NetBox Repository..."
# Clean previous install if exists to ensure fresh start
sudo rm -rf /opt/netbox
sudo mkdir -p /opt/netbox/
cd /opt/netbox/
sudo git clone -b v4.1.0 https://github.com/netbox-community/netbox.git .
verify_step "Git Clone"

echo ">> 6. Creating System User..."
if ! id "netbox" &>/dev/null; then
    sudo adduser --system --group netbox
fi
sudo chown --recursive netbox /opt/netbox/netbox/media/
sudo chown --recursive netbox /opt/netbox/netbox/reports/
sudo chown --recursive netbox /opt/netbox/netbox/scripts/
verify_step "User Creation"

echo ">> 7. Writing Configuration File..."
cd /opt/netbox/netbox/netbox/
cat <<EOF | sudo tee configuration.py > /dev/null
ALLOWED_HOSTS = ['{self.hostname}', 'localhost', '127.0.0.1', '*']
CSRF_TRUSTED_ORIGINS = ['{csrf_trusted}']
DATABASE = {{
    'NAME': 'netbox',
    'USER': 'netbox',
    'PASSWORD': '{db_password}',
    'HOST': '127.0.0.1',
    'PORT': '',
    'CONN_MAX_AGE': 300,
}}
REDIS = {{
    'tasks': {{
        'HOST': 'localhost',
        'PORT': 6379,
        'PASSWORD': '',
        'DATABASE': 0,
        'SSL': False,
    }},
    'caching': {{
        'HOST': 'localhost',
        'PORT': 6379,
        'PASSWORD': '',
        'DATABASE': 1,
        'SSL': False,
    }}
}}
SECRET_KEY = '{secret_key}'
ADMINS = []
MAINTENANCE_MODE = False
PLUGINS = []
EOF
verify_step "Configuration File"

echo ">> 8. Running Official Upgrade Script..."
# THE FIX: We modify the upgrade.sh to DISABLE mkdocs build to prevent freezing
# This allows us to use the official script safely.
sudo sed -i 's/mkdocs build/# mkdocs build/g' /opt/netbox/upgrade.sh

sudo chmod +x /opt/netbox/upgrade.sh
sudo /opt/netbox/upgrade.sh
verify_step "NetBox Upgrade Script"

echo ">> 9. Creating Admin User..."
source /opt/netbox/venv/bin/activate
cd /opt/netbox/netbox
export DJANGO_SUPERUSER_PASSWORD={self.password}
export DJANGO_SUPERUSER_USERNAME={self.username}
export DJANGO_SUPERUSER_EMAIL=admin@example.com

if python3 manage.py shell -c "from django.contrib.auth import get_user_model; User = get_user_model(); print(User.objects.filter(username='{self.username}').exists())" | grep -q "False"; then
    python3 manage.py createsuperuser --noinput
    echo "Superuser created."
else
    echo "Superuser already exists."
fi
verify_step "Admin Creation"

echo ">> 10. Configuring Nginx & SSL..."
sudo cp /opt/netbox/contrib/gunicorn.py /opt/netbox/gunicorn.py
sudo cp /opt/netbox/contrib/*.service /etc/systemd/system/
sudo systemctl daemon-reload
sudo systemctl enable netbox netbox-rq
sudo cp /opt/netbox/contrib/nginx.conf /etc/nginx/sites-available/netbox
sudo rm -f /etc/nginx/sites-enabled/default
sudo ln -s /etc/nginx/sites-available/netbox /etc/nginx/sites-enabled/netbox || true

# Set Server Name
sudo sed -i "s/server_name netbox.example.com;/server_name {self.hostname};/" /etc/nginx/sites-available/netbox

# Create Self-Signed SSL
sudo mkdir -p /etc/ssl/private /etc/ssl/certs
sudo openssl req -x509 -nodes -days 365 -newkey rsa:2048 \\
-keyout /etc/ssl/private/netbox.key \\
-out /etc/ssl/certs/netbox.crt \\
-subj "/C=US/ST=State/L=City/O=NetBox/OU=IT/CN={self.hostname}"
verify_step "SSL Generation"

# Verify Nginx Syntax
sudo nginx -t
verify_step "Nginx Config Test"

echo ">> 11. Finalizing & Restarting Services..."
sudo ufw allow 80/tcp
sudo ufw allow 443/tcp
sudo systemctl restart nginx
sudo systemctl restart netbox netbox-rq
verify_step "Service Restart"

echo ">> Checking Health..."
sleep 15
# Simple check if port 443 is listening and responding
if curl -k -I "https://localhost/" | grep -q "200 OK"; then
    echo "✅ HEALTH CHECK PASSED: NetBox is UP!"
else
    echo "⚠️ WARNING: NetBox started but might be slow to respond initially."
fi

IP=$(hostname -I | awk '{{print $1}}')
echo "✅ Installation completed successfully! Access URL: https://$IP/"
"""

    def monitor_ssh_channel(self, channel, ssh, remote_path):
        output_buffer = ""
        while not channel.exit_status_ready() and self.is_running:
            time.sleep(0.5)
            if channel.recv_ready():
                try:
                    data = channel.recv(1024).decode('utf-8')
                except UnicodeDecodeError:
                    data = str(channel.recv(1024))
                
                output_buffer += data
                self.output_received.emit(data.strip())
                
                # Progress Logic
                if "Updating system" in output_buffer: 
                    self.progress_updated.emit(10)
                elif "Dependencies Installation" in output_buffer: 
                    self.progress_updated.emit(25)
                elif "Cloning NetBox" in output_buffer: 
                    self.progress_updated.emit(45)
                elif "NetBox Upgrade Script" in output_buffer: 
                    self.progress_updated.emit(65)
                elif "Admin Creation" in output_buffer: 
                    self.progress_updated.emit(85)
                elif "Finalizing" in output_buffer: 
                    self.progress_updated.emit(95)
                    
                if "Installation completed successfully" in output_buffer:
                    self.detected_ip = f"https://{self.hostname}/"
                    
                if len(output_buffer) > 10000:
                    output_buffer = output_buffer[-5000:]

        ssh.exec_command(f"sudo rm -f {remote_path}")
        exit_status = channel.recv_exit_status()
        ssh.close()
        
        if exit_status == 0:
            if not self.detected_ip: 
                self.detected_ip = f"https://{self.hostname}/"
            self.url_generated.emit(self.detected_ip)
            self.finished.emit(True, "NetBox Installed Successfully!")
        else:
            self.finished.emit(False, f"Process failed with exit code: {exit_status}")

    def stop(self):
        self.is_running = False

